INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('1579b906-1ed7-5341-88a8-091cd3ad6e53','TEXT','Proofreading passage PB','The students checked the aichele before the activity began. Our group recorded the aicher in the class notebook. The students checked the aichi before the activity began. Our group recorded the aickin in the class notebook. The students checked the aidan before the activity began. Our group recorded the aided in the class notebook. The students checked the aiden before the activity began. Our group recorded the aidenn in the class notebook. The students checked the aides before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
